import React, {useState, useEffect} from'react'

export default function ItemTile({item}){

    function handleClick(){
        console.log('Opening Page')
    }

    return(
        <div className="item-tile" onClick={handleClick}>
            <img src={item.image} alt={item.itemname} />
            <div className="item-tile-info">
                <p className="item-tile-name">{item.itemname}</p>
                <div className="item-tile-props">
                    {item.itemprops.map((prop, i) => (
                        <div className="item-tile-prop" key={i}>
                            <span>{prop.label}</span>
                            <span>{prop.value}</span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    )


}
